parameters.jsCode:
const body = $input.first().json.body ?? {};

const htmlEncodeOnly = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const defangLinks = (value) => String(value ?? '')
  .replace(/https:\/\//gi, 'https[:]//')
  .replace(/http:\/\//gi, 'http[:]//')
  .replace(/www\./gi, 'www[.]')
  .replace(
    /\b([a-z0-9-]+(?:\.[a-z0-9-]+)+)(\/[^\s<>"']*)?/gi,
    (match) => match.replace(/\./g, '[.]')
  );

const safeText = (value) => htmlEncodeOnly(defangLinks(value));

const cleanSubjectText = (value) => String(value ?? '')
  .replace(/[\r\n]+/g, ' ')
  .trim();

const sanitizePhone = (value) => {
  const text = String(value ?? '').trim();

  return text
    .replace(/[^\d+]/g, '')
    .replace(/(?!^)\+/g, '');
};

return [
  {
    json: {
      ...$input.first().json,
      emailContent: {
        bookingNumber: safeText(body.bookingNumber),
        bookerName: safeText(body.bookerName),
        branchName: safeText(body.branchName),
        roomTypeName: safeText(body.roomTypeName),
        checkInDate: safeText(body.checkInDate),
        checkOutDate: safeText(body.checkOutDate),
        totalAmount: safeText(body.totalAmount),
        branchAddress: safeText(body.branchAddress),
        branchPhoneText: safeText(sanitizePhone(body.branchPhone)),
        branchPhoneHref: sanitizePhone(body.branchPhone),
        subjectBranchName: cleanSubjectText(body.branchName).replace(/[<>]/g, '')
      }
    }
  }
];
